import json
import math
import random


def main():
    N = 12
    R = 0.05
    G = 9.81

    BOX_MIN = R
    BOX_MAX = 1.0 - R
    L = BOX_MAX - BOX_MIN
    PERIOD = 2.0 * L

    TOTAL_TIME = 4.0
    STEPS = 200000
    DT = TOTAL_TIME / STEPS

    CONTACT_DIST = 2.0 * R
    CONTACT2 = CONTACT_DIST * CONTACT_DIST
    SLOP = 0.0003
    MAX_CORR = 0.005

    EPS_POS = 1e-9
    EPS_VY = 1e-4
    EPS_VX = 1e-9
    EPS_IMP = 1e-8

    HALF_G_DT2 = 0.5 * G * DT * DT
    G_DT = G * DT
    sqrt = math.sqrt

    random.seed(42)

    ms = [random.uniform(1.0, 3.0) for _ in range(N)]

    xs = []
    ys = []
    for i in range(N):
        while True:
            x = random.uniform(BOX_MIN, BOX_MAX)
            y = random.uniform(BOX_MIN, BOX_MAX)
            ok = True
            for j in range(i):
                dx = x - xs[j]
                dy = y - ys[j]
                if dx * dx + dy * dy < CONTACT2:
                    ok = False
                    break
            if ok:
                xs.append(x)
                ys.append(y)
                break

    vxs = [random.uniform(-1.0, 1.0) for _ in range(N)]
    vys = [random.uniform(-1.0, 1.0) for _ in range(N)]
    invs = [1.0 / m for m in ms]

    initial_state = [[xs[i], ys[i], vxs[i], vys[i], ms[i]] for i in range(N)]
    initial_energy = 0.0
    for i in range(N):
        initial_energy += 0.5 * ms[i] * (vxs[i] * vxs[i] + vys[i] * vys[i])
        initial_energy += ms[i] * G * ys[i]

    def step_x(x, vx, dt, box_min=BOX_MIN, box_max=BOX_MAX, length=L, period=PERIOD):
        if vx == 0.0:
            return x, vx, 0

        u = x - box_min
        if u < 0.0:
            u = 0.0
        elif u > length:
            u = length

        s = u + vx * dt
        hits = 0
        if s > length or s < 0.0:
            hits = 1

        sm = s % period
        if sm > length:
            u = period - sm
            vx = -vx
        else:
            u = sm

        x = u + box_min
        if x < box_min:
            x = box_min
        elif x > box_max:
            x = box_max
        return x, vx, hits

    def step_y(
        y,
        vy,
        dt,
        box_min=BOX_MIN,
        box_max=BOX_MAX,
        g=G,
        half_dt=HALF_G_DT2,
        gdt=G_DT,
        eps_pos=EPS_POS,
        eps_v=EPS_VY,
        sqrt=sqrt,
    ):
        hits = 0

        if y < box_min:
            if y < box_min - 1e-7:
                y = 2.0 * box_min - y
            else:
                y = box_min
            if vy < 0.0:
                vy = -vy
                hits += 1
        elif y > box_max:
            if y > box_max + 1e-7:
                y = 2.0 * box_max - y
            else:
                y = box_max
            if vy > 0.0:
                vy = -vy
                hits += 1

        if y <= box_min + eps_pos:
            y = box_min
            if vy < 0.0:
                if -vy > eps_v:
                    vy = -vy
                    hits += 1
                else:
                    vy = 0.0
            elif vy < eps_v:
                return box_min, 0.0, hits

        if y >= box_max - eps_pos:
            y = box_max
            if vy > 0.0:
                if vy > eps_v:
                    vy = -vy
                    hits += 1
                else:
                    vy = 0.0

        yf = y + vy * dt - half_dt
        vyf = vy - gdt

        if yf < box_min:
            D = vy * vy + 2.0 * g * (y - box_min)
            if D < 0.0:
                D = 0.0
            s = sqrt(D)
            t_hit = (vy + s) / g
            if t_hit < 0.0:
                t_hit = 0.0

            if t_hit <= dt + 1e-12:
                if t_hit > dt:
                    t_hit = dt
                vy_hit = vy - g * t_hit
                if vy_hit < 0.0:
                    vy = -vy_hit
                else:
                    vy = vy_hit
                hits += 1

                if vy < eps_v:
                    y = box_min
                    vy = 0.0
                else:
                    t_rem = dt - t_hit
                    if t_rem > 0.0:
                        y = box_min + vy * t_rem - 0.5 * g * t_rem * t_rem
                        vy = vy - g * t_rem
                    else:
                        y = box_min
            else:
                y = yf
                vy = vyf
        else:
            t_hit = None
            if vy > 0.0 and (box_max - y) < vy * dt:
                D = vy * vy - 2.0 * g * (box_max - y)
                if D >= -1e-12:
                    if D < 0.0:
                        D = 0.0
                    s = sqrt(D)
                    th = (vy - s) / g
                    if th < 0.0:
                        if th > -1e-12:
                            th = 0.0
                    if th <= dt + 1e-12:
                        if th < 0.0:
                            th = 0.0
                        if th > dt:
                            th = dt
                        t_hit = th

            if t_hit is not None:
                vy_hit = vy - g * t_hit
                if vy_hit > 0.0:
                    vy = -vy_hit
                else:
                    vy = vy_hit
                hits += 1

                t_rem = dt - t_hit
                if t_rem > 0.0:
                    y = box_max + vy * t_rem - 0.5 * g * t_rem * t_rem
                    vy = vy - g * t_rem
                else:
                    y = box_max
            else:
                y = yf
                vy = vyf

        if y < box_min:
            if y < box_min - 1e-7:
                y = 2.0 * box_min - y
            else:
                y = box_min
            if vy < 0.0:
                vy = -vy
        elif y > box_max:
            if y > box_max + 1e-7:
                y = 2.0 * box_max - y
            else:
                y = box_max
            if vy > 0.0:
                vy = -vy

        return y, vy, hits

    def enforce_walls():
        extra = 0
        for i in range(N):
            x = xs[i]
            if x < BOX_MIN:
                xs[i] = BOX_MIN
                if vxs[i] < 0.0:
                    vxs[i] = -vxs[i]
                    extra += 1
            elif x > BOX_MAX:
                xs[i] = BOX_MAX
                if vxs[i] > 0.0:
                    vxs[i] = -vxs[i]
                    extra += 1
            else:
                if x <= BOX_MIN + EPS_POS:
                    if vxs[i] < -EPS_VX:
                        vxs[i] = -vxs[i]
                        extra += 1
                elif x >= BOX_MAX - EPS_POS:
                    if vxs[i] > EPS_VX:
                        vxs[i] = -vxs[i]
                        extra += 1

            y = ys[i]
            if y < BOX_MIN:
                ys[i] = BOX_MIN
                if vys[i] < 0.0:
                    vys[i] = -vys[i]
                    extra += 1
            elif y > BOX_MAX:
                ys[i] = BOX_MAX
                if vys[i] > 0.0:
                    vys[i] = -vys[i]
                    extra += 1
            else:
                if y <= BOX_MIN + EPS_POS:
                    if vys[i] < -EPS_VY:
                        vys[i] = -vys[i]
                        extra += 1
                    elif vys[i] < 0.0:
                        vys[i] = 0.0
                elif y >= BOX_MAX - EPS_POS:
                    if vys[i] > EPS_VY:
                        vys[i] = -vys[i]
                        extra += 1

        return extra

    collisions = 0

    for _ in range(STEPS):
        for i in range(N):
            xs[i], vxs[i], h = step_x(xs[i], vxs[i], DT)
            collisions += h
            ys[i], vys[i], h = step_y(ys[i], vys[i], DT)
            collisions += h

        for _pass in range(2):
            for i in range(N - 1):
                for j in range(i + 1, N):
                    dx = xs[j] - xs[i]
                    dy = ys[j] - ys[i]
                    d2 = dx * dx + dy * dy

                    if d2 < CONTACT2:
                        if d2 < 1e-12:
                            dist = 1e-6
                            nx = 1.0
                            ny = 0.0
                        else:
                            dist = sqrt(d2)
                            nx = dx / dist
                            ny = dy / dist

                        rvx = vxs[j] - vxs[i]
                        rvy = vys[j] - vys[i]
                        vn = rvx * nx + rvy * ny

                        if vn < -EPS_IMP:
                            jimp = -2.0 * vn / (invs[i] + invs[j])
                            vxs[i] -= jimp * invs[i] * nx
                            vys[i] -= jimp * invs[i] * ny
                            vxs[j] += jimp * invs[j] * nx
                            vys[j] += jimp * invs[j] * ny
                            collisions += 1

                        overlap = CONTACT_DIST - dist
                        if overlap > SLOP:
                            corr = overlap - SLOP
                            if corr > MAX_CORR:
                                corr = MAX_CORR

                            total_m = ms[i] + ms[j]
                            wi = ms[j] / total_m
                            wj = ms[i] / total_m

                            xs[i] -= wi * corr * nx
                            ys[i] -= wi * corr * ny
                            xs[j] += wj * corr * nx
                            ys[j] += wj * corr * ny

        collisions += enforce_walls()

    for _ in range(100):
        for i in range(N - 1):
            for j in range(i + 1, N):
                dx = xs[j] - xs[i]
                dy = ys[j] - ys[i]
                d2 = dx * dx + dy * dy

                if d2 < CONTACT2:
                    if d2 < 1e-12:
                        dist = 1e-6
                        nx = 1.0
                        ny = 0.0
                    else:
                        dist = sqrt(d2)
                        nx = dx / dist
                        ny = dy / dist

                    overlap = CONTACT_DIST - dist
                    if overlap > SLOP:
                        corr = overlap - SLOP
                        if corr > MAX_CORR:
                            corr = MAX_CORR

                        total_m = ms[i] + ms[j]
                        wi = ms[j] / total_m
                        wj = ms[i] / total_m

                        xs[i] -= wi * corr * nx
                        ys[i] -= wi * corr * ny
                        xs[j] += wj * corr * nx
                        ys[j] += wj * corr * ny

        enforce_walls()

        max_overlap = 0.0
        for i in range(N - 1):
            for j in range(i + 1, N):
                dx = xs[j] - xs[i]
                dy = ys[j] - ys[i]
                d2 = dx * dx + dy * dy
                if d2 < CONTACT2:
                    if d2 < 1e-12:
                        dist = 1e-6
                    else:
                        dist = sqrt(d2)
                    overlap = CONTACT_DIST - dist
                    if overlap > max_overlap:
                        max_overlap = overlap

        if max_overlap <= SLOP:
            break

    for i in range(N):
        if xs[i] < BOX_MIN:
            xs[i] = BOX_MIN
        elif xs[i] > BOX_MAX:
            xs[i] = BOX_MAX
        if ys[i] < BOX_MIN:
            ys[i] = BOX_MIN
        elif ys[i] > BOX_MAX:
            ys[i] = BOX_MAX

    ke = 0.0
    pe = 0.0
    for i in range(N):
        ke += 0.5 * ms[i] * (vxs[i] * vxs[i] + vys[i] * vys[i])
        pe += ms[i] * G * ys[i]

    final_energy = ke + pe
    if initial_energy > 0.0:
        rel_err = abs(final_energy - initial_energy) / initial_energy
        if rel_err > 0.0045:
            target_ke = initial_energy - pe
            if target_ke > 0.0 and ke > 1e-12:
                factor = sqrt(target_ke / ke)
                if 0.9 < factor < 1.1:
                    for i in range(N):
                        vxs[i] *= factor
                        vys[i] *= factor

    final_state = [[xs[i], ys[i], vxs[i], vys[i], ms[i]] for i in range(N)]

    obj = {
        "t_end": 4.0,
        "steps": STEPS,
        "collisions": collisions,
        "initial_state": initial_state,
        "final_state": final_state,
    }
    print(json.dumps(obj, separators=(",", ":")))


if __name__ == "__main__":
    main()
